using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;
using System;
using System.Collections.Generic;

namespace ContosoUniversity.Tests.Helpers
{
    public static class TestDbContextFactory
    {
        public static SchoolContext Create(string? dbName = null)
        {
            dbName ??= Guid.NewGuid().ToString();
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: dbName)
                .Options;

            var context = new SchoolContext(options);
            context.Database.EnsureCreated();
            return context;
        }

        public static SchoolContext CreateWithSeedData(string? dbName = null)
        {
            var context = Create(dbName);
            SeedData(context);
            return context;
        }

        private static void SeedData(SchoolContext context)
        {
            var instructors = new List<Instructor>
            {
                new Instructor { ID = 1, LastName = "Smith", FirstMidName = "John", HireDate = new DateTime(2010, 1, 15),
                    CourseAssignments = new List<CourseAssignment>(),
                    OfficeAssignment = new OfficeAssignment { Location = "Room 101" } },
                new Instructor { ID = 2, LastName = "Jones", FirstMidName = "Jane", HireDate = new DateTime(2012, 6, 1),
                    CourseAssignments = new List<CourseAssignment>() },
            };

            var departments = new List<Department>
            {
                new Department { DepartmentID = 1, Name = "Engineering", Budget = 100000m, StartDate = new DateTime(2000, 9, 1), InstructorID = 1 },
                new Department { DepartmentID = 2, Name = "Mathematics", Budget = 50000m, StartDate = new DateTime(2005, 9, 1), InstructorID = 2 },
            };

            var courses = new List<Course>
            {
                new Course { CourseID = 1001, Title = "Calculus", Credits = 4, DepartmentID = 2,
                    Enrollments = new List<Enrollment>(), CourseAssignments = new List<CourseAssignment>() },
                new Course { CourseID = 2001, Title = "Programming", Credits = 3, DepartmentID = 1,
                    Enrollments = new List<Enrollment>(), CourseAssignments = new List<CourseAssignment>() },
            };

            var students = new List<Student>
            {
                new Student { ID = 10, LastName = "Doe", FirstMidName = "Alice", EnrollmentDate = new DateTime(2020, 9, 1),
                    Enrollments = new List<Enrollment>() },
                new Student { ID = 11, LastName = "Brown", FirstMidName = "Bob", EnrollmentDate = new DateTime(2021, 9, 1),
                    Enrollments = new List<Enrollment>() },
            };

            context.Instructors.AddRange(instructors);
            context.Departments.AddRange(departments);
            context.Courses.AddRange(courses);
            context.Students.AddRange(students);

            context.Enrollments.Add(new Enrollment { EnrollmentID = 1, CourseID = 1001, StudentID = 10, Grade = Grade.A });
            context.Enrollments.Add(new Enrollment { EnrollmentID = 2, CourseID = 2001, StudentID = 10, Grade = Grade.B });
            context.Enrollments.Add(new Enrollment { EnrollmentID = 3, CourseID = 1001, StudentID = 11, Grade = null });

            // Link course assignments
            context.CourseAssignments.Add(new CourseAssignment { InstructorID = 1, CourseID = 2001 });
            context.CourseAssignments.Add(new CourseAssignment { InstructorID = 2, CourseID = 1001 });

            context.SaveChanges();
        }
    }
}

