using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.EntityFrameworkCore;
using System;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests.Data
{
    public class DbInitializerTests
    {
        [Fact]
        public void Initialize_EmptyDatabase_SeedsAllEntities()
        {
            using var context = TestDbContextFactory.Create();

            DbInitializer.Initialize(context);

            Assert.Equal(8, context.Students.Count());
            Assert.Equal(5, context.Instructors.Count());
            Assert.Equal(4, context.Departments.Count());
            Assert.Equal(7, context.Courses.Count());
            Assert.Equal(3, context.OfficeAssignments.Count());
            Assert.Equal(8, context.CourseAssignments.Count());
            Assert.True(context.Enrollments.Count() >= 11);
        }

        [Fact]
        public void Initialize_AlreadySeeded_DoesNotDuplicate()
        {
            using var context = TestDbContextFactory.Create();

            DbInitializer.Initialize(context);
            var studentCountAfterFirst = context.Students.Count();

            DbInitializer.Initialize(context);
            var studentCountAfterSecond = context.Students.Count();

            Assert.Equal(studentCountAfterFirst, studentCountAfterSecond);
        }

        [Fact]
        public void Initialize_CreatesCorrectCourseAssignments()
        {
            using var context = TestDbContextFactory.Create();

            DbInitializer.Initialize(context);

            var chemistry = context.Courses.Single(c => c.Title == "Chemistry");
            var chemAssignments = context.CourseAssignments.Where(ca => ca.CourseID == chemistry.CourseID).ToList();
            Assert.Equal(2, chemAssignments.Count);
        }

        [Fact]
        public void Initialize_SetsCorrectGrades()
        {
            using var context = TestDbContextFactory.Create();

            DbInitializer.Initialize(context);

            var alexander = context.Students.Single(s => s.LastName == "Alexander");
            var enrollments = context.Enrollments.Where(e => e.StudentID == alexander.ID).ToList();
            Assert.Contains(enrollments, e => e.Grade == Grade.A);
            Assert.Contains(enrollments, e => e.Grade == Grade.B);
            Assert.Contains(enrollments, e => e.Grade == Grade.C);
        }
    }

    public class SchoolContextTests
    {
        [Fact]
        public void OnModelCreating_ConfiguresCourseAssignmentCompositeKey()
        {
            using var context = TestDbContextFactory.Create();

            var entityType = context.Model.FindEntityType(typeof(CourseAssignment));
            var primaryKey = entityType!.FindPrimaryKey();

            Assert.NotNull(primaryKey);
            Assert.Equal(2, primaryKey.Properties.Count);
            Assert.Contains(primaryKey.Properties, p => p.Name == "CourseID");
            Assert.Contains(primaryKey.Properties, p => p.Name == "InstructorID");
        }

        [Fact]
        public void OnModelCreating_ConfiguresTPHInheritance()
        {
            using var context = TestDbContextFactory.Create();

            // Both Student and Instructor should use the Person table
            var studentEntity = context.Model.FindEntityType(typeof(Student));
            var instructorEntity = context.Model.FindEntityType(typeof(Instructor));

            Assert.Equal("Person", studentEntity!.GetTableName());
            Assert.Equal("Person", instructorEntity!.GetTableName());
        }

        [Fact]
        public void OnModelCreating_ConfiguresOfficeAssignmentRelationship()
        {
            using var context = TestDbContextFactory.Create();

            var entity = context.Model.FindEntityType(typeof(OfficeAssignment));
            var pk = entity!.FindPrimaryKey();

            Assert.Single(pk!.Properties);
            Assert.Equal("InstructorID", pk.Properties[0].Name);
        }

        [Fact]
        public void DbSets_AreAccessible()
        {
            using var context = TestDbContextFactory.Create();

            Assert.NotNull(context.Courses);
            Assert.NotNull(context.Students);
            Assert.NotNull(context.Instructors);
            Assert.NotNull(context.Departments);
            Assert.NotNull(context.Enrollments);
            Assert.NotNull(context.OfficeAssignments);
            Assert.NotNull(context.CourseAssignments);
            Assert.NotNull(context.Notifications);
            Assert.NotNull(context.People);
        }
    }
}

using ContosoUniversity.Models;
using ContosoUniversity.Models.SchoolViewModels;
using System;
using System.Collections.Generic;
using Xunit;

namespace ContosoUniversity.Tests.Models
{
    public class ModelTests
    {
        [Fact]
        public void Person_FullName_ReturnsCombination()
        {
            var student = new Student { LastName = "Doe", FirstMidName = "John" };

            Assert.Equal("Doe, John", student.FullName);
        }

        [Fact]
        public void Instructor_FullName_ReturnsCombination()
        {
            var instructor = new Instructor { LastName = "Smith", FirstMidName = "Jane" };

            Assert.Equal("Smith, Jane", instructor.FullName);
        }

        [Theory]
        [InlineData("A", "B", "A, B")]
        [InlineData("LastOnly", "First", "LastOnly, First")]
        public void Person_FullName_Parameterized(string last, string first, string expected)
        {
            var person = new Student { LastName = last, FirstMidName = first };

            Assert.Equal(expected, person.FullName);
        }

        [Fact]
        public void Student_Properties_SetCorrectly()
        {
            var date = new DateTime(2023, 9, 1);
            var student = new Student
            {
                ID = 1,
                LastName = "Test",
                FirstMidName = "Student",
                EnrollmentDate = date,
                Enrollments = new List<Enrollment>()
            };

            Assert.Equal(1, student.ID);
            Assert.Equal("Test", student.LastName);
            Assert.Equal("Student", student.FirstMidName);
            Assert.Equal(date, student.EnrollmentDate);
            Assert.Empty(student.Enrollments);
        }

        [Fact]
        public void Instructor_Properties_SetCorrectly()
        {
            var date = new DateTime(2010, 1, 15);
            var instructor = new Instructor
            {
                ID = 5,
                LastName = "Prof",
                FirstMidName = "Test",
                HireDate = date,
                CourseAssignments = new List<CourseAssignment>(),
                OfficeAssignment = new OfficeAssignment { Location = "Room 1" }
            };

            Assert.Equal(5, instructor.ID);
            Assert.Equal(date, instructor.HireDate);
            Assert.NotNull(instructor.OfficeAssignment);
            Assert.Equal("Room 1", instructor.OfficeAssignment.Location);
        }

        [Fact]
        public void Course_Properties_SetCorrectly()
        {
            var course = new Course
            {
                CourseID = 1001,
                Title = "Test Course",
                Credits = 3,
                DepartmentID = 1,
                TeachingMaterialImagePath = "/path/to/image.jpg"
            };

            Assert.Equal(1001, course.CourseID);
            Assert.Equal("Test Course", course.Title);
            Assert.Equal(3, course.Credits);
            Assert.Equal(1, course.DepartmentID);
            Assert.Equal("/path/to/image.jpg", course.TeachingMaterialImagePath);
        }

        [Fact]
        public void Department_Properties_SetCorrectly()
        {
            var dept = new Department
            {
                DepartmentID = 1,
                Name = "Science",
                Budget = 50000m,
                StartDate = new DateTime(2000, 1, 1),
                InstructorID = 2,
                RowVersion = new byte[] { 1, 2, 3 }
            };

            Assert.Equal(1, dept.DepartmentID);
            Assert.Equal("Science", dept.Name);
            Assert.Equal(50000m, dept.Budget);
            Assert.Equal(2, dept.InstructorID);
            Assert.Equal(new byte[] { 1, 2, 3 }, dept.RowVersion);
        }

        [Fact]
        public void Enrollment_Properties_SetCorrectly()
        {
            var enrollment = new Enrollment
            {
                EnrollmentID = 1,
                CourseID = 100,
                StudentID = 10,
                Grade = Grade.B
            };

            Assert.Equal(1, enrollment.EnrollmentID);
            Assert.Equal(100, enrollment.CourseID);
            Assert.Equal(10, enrollment.StudentID);
            Assert.Equal(Grade.B, enrollment.Grade);
        }

        [Fact]
        public void Enrollment_NullGrade_IsAllowed()
        {
            var enrollment = new Enrollment { Grade = null };

            Assert.Null(enrollment.Grade);
        }

        [Fact]
        public void Notification_Properties_SetCorrectly()
        {
            var now = DateTime.Now;
            var notification = new Notification
            {
                Id = 1,
                EntityType = "Student",
                EntityId = "5",
                Operation = "CREATE",
                Message = "Test message",
                CreatedAt = now,
                CreatedBy = "Admin",
                IsRead = false,
                ReadAt = null
            };

            Assert.Equal(1, notification.Id);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("5", notification.EntityId);
            Assert.Equal("CREATE", notification.Operation);
            Assert.Equal("Test message", notification.Message);
            Assert.Equal(now, notification.CreatedAt);
            Assert.Equal("Admin", notification.CreatedBy);
            Assert.False(notification.IsRead);
            Assert.Null(notification.ReadAt);
        }

        [Fact]
        public void OfficeAssignment_Properties_SetCorrectly()
        {
            var oa = new OfficeAssignment
            {
                InstructorID = 3,
                Location = "Building A"
            };

            Assert.Equal(3, oa.InstructorID);
            Assert.Equal("Building A", oa.Location);
        }

        [Fact]
        public void CourseAssignment_Properties_SetCorrectly()
        {
            var ca = new CourseAssignment
            {
                InstructorID = 1,
                CourseID = 100
            };

            Assert.Equal(1, ca.InstructorID);
            Assert.Equal(100, ca.CourseID);
        }

        [Fact]
        public void InstructorIndexData_Properties_SetCorrectly()
        {
            var data = new InstructorIndexData
            {
                Instructors = new List<Instructor>(),
                Courses = new List<Course>(),
                Enrollments = new List<Enrollment>()
            };

            Assert.NotNull(data.Instructors);
            Assert.NotNull(data.Courses);
            Assert.NotNull(data.Enrollments);
        }

        [Fact]
        public void AssignedCourseData_Properties_SetCorrectly()
        {
            var acd = new AssignedCourseData
            {
                CourseID = 10,
                Title = "Physics",
                Assigned = true
            };

            Assert.Equal(10, acd.CourseID);
            Assert.Equal("Physics", acd.Title);
            Assert.True(acd.Assigned);
        }

        [Fact]
        public void EnrollmentDateGroup_Properties_SetCorrectly()
        {
            var group = new EnrollmentDateGroup
            {
                EnrollmentDate = new DateTime(2023, 9, 1),
                StudentCount = 5
            };

            Assert.Equal(new DateTime(2023, 9, 1), group.EnrollmentDate);
            Assert.Equal(5, group.StudentCount);
        }

        [Fact]
        public void EntityOperation_HasExpectedValues()
        {
            Assert.Equal(0, (int)EntityOperation.CREATE);
            Assert.Equal(1, (int)EntityOperation.UPDATE);
            Assert.Equal(2, (int)EntityOperation.DELETE);
        }

        [Fact]
        public void Grade_HasExpectedValues()
        {
            Assert.Equal(0, (int)Grade.A);
            Assert.Equal(1, (int)Grade.B);
            Assert.Equal(2, (int)Grade.C);
            Assert.Equal(3, (int)Grade.D);
            Assert.Equal(4, (int)Grade.F);
        }
    }
}

