using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.EntityFrameworkCore;
using System;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests.Data
{
    public class DbInitializerTests
    {
        [Fact]
        public void Initialize_EmptyDatabase_SeedsAllEntities()
        {
            using var context = TestDbContextFactory.Create();

            DbInitializer.Initialize(context);

            Assert.Equal(8, context.Students.Count());
            Assert.Equal(5, context.Instructors.Count());
            Assert.Equal(4, context.Departments.Count());
            Assert.Equal(7, context.Courses.Count());
            Assert.Equal(3, context.OfficeAssignments.Count());
            Assert.Equal(8, context.CourseAssignments.Count());
            Assert.True(context.Enrollments.Count() >= 11);
        }

        [Fact]
        public void Initialize_AlreadySeeded_DoesNotDuplicate()
        {
            using var context = TestDbContextFactory.Create();

            DbInitializer.Initialize(context);
            var studentCountAfterFirst = context.Students.Count();

            DbInitializer.Initialize(context);
            var studentCountAfterSecond = context.Students.Count();

            Assert.Equal(studentCountAfterFirst, studentCountAfterSecond);
        }

        [Fact]
        public void Initialize_CreatesCorrectCourseAssignments()
        {
            using var context = TestDbContextFactory.Create();

            DbInitializer.Initialize(context);

            var chemistry = context.Courses.Single(c => c.Title == "Chemistry");
            var chemAssignments = context.CourseAssignments.Where(ca => ca.CourseID == chemistry.CourseID).ToList();
            Assert.Equal(2, chemAssignments.Count);
        }

        [Fact]
        public void Initialize_SetsCorrectGrades()
        {
            using var context = TestDbContextFactory.Create();

            DbInitializer.Initialize(context);

            var alexander = context.Students.Single(s => s.LastName == "Alexander");
            var enrollments = context.Enrollments.Where(e => e.StudentID == alexander.ID).ToList();
            Assert.Contains(enrollments, e => e.Grade == Grade.A);
            Assert.Contains(enrollments, e => e.Grade == Grade.B);
            Assert.Contains(enrollments, e => e.Grade == Grade.C);
        }
    }

    public class SchoolContextTests
    {
        [Fact]
        public void OnModelCreating_ConfiguresCourseAssignmentCompositeKey()
        {
            using var context = TestDbContextFactory.Create();

            var entityType = context.Model.FindEntityType(typeof(CourseAssignment));
            var primaryKey = entityType!.FindPrimaryKey();

            Assert.NotNull(primaryKey);
            Assert.Equal(2, primaryKey.Properties.Count);
            Assert.Contains(primaryKey.Properties, p => p.Name == "CourseID");
            Assert.Contains(primaryKey.Properties, p => p.Name == "InstructorID");
        }

        [Fact]
        public void OnModelCreating_ConfiguresTPHInheritance()
        {
            using var context = TestDbContextFactory.Create();

            var studentEntity = context.Model.FindEntityType(typeof(Student));
            var instructorEntity = context.Model.FindEntityType(typeof(Instructor));

            Assert.Equal("Person", studentEntity!.GetTableName());
            Assert.Equal("Person", instructorEntity!.GetTableName());
        }

        [Fact]
        public void OnModelCreating_ConfiguresOfficeAssignmentRelationship()
        {
            using var context = TestDbContextFactory.Create();

            var entity = context.Model.FindEntityType(typeof(OfficeAssignment));
            var pk = entity!.FindPrimaryKey();

            Assert.Single(pk!.Properties);
            Assert.Equal("InstructorID", pk.Properties[0].Name);
        }

        [Fact]
        public void DbSets_AreAccessible()
        {
            using var context = TestDbContextFactory.Create();

            Assert.NotNull(context.Courses);
            Assert.NotNull(context.Students);
            Assert.NotNull(context.Instructors);
            Assert.NotNull(context.Departments);
            Assert.NotNull(context.Enrollments);
            Assert.NotNull(context.OfficeAssignments);
            Assert.NotNull(context.CourseAssignments);
            Assert.NotNull(context.Notifications);
            Assert.NotNull(context.People);
        }
    }
}

